596	            preview.layout = persistence::load_last_preview_layout(D::name(), cx)
597	                .log_err()
598	                .flatten()
599	                .unwrap_or_default();
600	        };
601	        let has_preview = preview.is_some();
602	        let persisted_shape =
603	            persistence::try_load_shape(D::name(), preview.as_ref().map(|p| p.layout), cx)
604	                .log_err()
605	                .flatten();
606	        // Every picker opens at the standard "simple" size: a fixed width and a
607	        // standard max height it shrinks below when there's little content.
608	        // Showing a preview expands it to the larger "telescope" size (see
609	        // `default_shape_for_layout`).
610	        let default_shape = shape::Centered::simple();
611	        let initial_layout = preview
612	            .as_ref()
613	            .map(|p| p.layout)
614	            .unwrap_or(preview::Layout::Hidden);
615	        let mut size_bounds = shape::SizeBounds::default();
616	        // For a plain picker the whole-picker minimum is just its opening width,
617	        // so it can't be resized/clamped narrower than it opens. Preview pickers
618	        // keep the standard per-pane minimums.
619	        if !has_preview && let Some(width) = default_shape.width.as_rems() {
620	            size_bounds.min_results.width = width;
621	        }
622	        let mut this = Self {
