624	            head,
625	            element_container,
626	            pending_update_matches: None,
627	            confirm_on_update: None,
628	            select_instead_of_open: false,
629	            preview,
630	            shape_loaded_from_persistence: persisted_shape.is_some(),
631	            shape: persisted_shape.unwrap_or_else(|| {
632	                shape::Shape::HorizontallyCentered(default_shape_for_layout(
633	                    default_shape,
634	                    initial_layout,
635	                ))
636	            }),
